import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../Estilo/Detalhes.css'; // Caminho para o CSS atualizado

function Detalhes() {
  const [data, setData] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await axios.get('https://app.beeceptor.com/console/listausuarios');
        console.log('Dados recebidos:', response.data);
        setData(response.data);
      } catch (error) {
        console.error('Ocorreu um erro ao buscar os dados:', error);
      }
    };

    fetchData();
  }, []);

  return (
    <div className="App min-h-screen bg-gray-100 flex items-center justify-center">
      <div className="w-full max-w-md p-6 bg-white rounded-lg shadow-md">
        <h1 className="text-2xl font-bold mb-6 text-gray-800">Detalhes do Cadastro</h1>
        {Array.isArray(data) && data.length === 0 ? (
          <p>Nenhum dado cadastrado.</p>
        ) : (
          Array.isArray(data) ? (
            data.map((item, index) => (
              <div key={index} className="mb-4">
                <p><strong>Nome Completo:</strong> {item.nomeCompleto}</p>
                <p><strong>Data de Nascimento:</strong> {item.dataNascimento}</p>
                <p><strong>Telefone:</strong> {item.telefone}</p>
              </div>
            ))
          ) : (
            <p>Ocorreu um erro ao carregar os dados.</p>
          )
        )}
      </div>
    </div>
  );
}

export default Detalhes;
